INSERT INTO `tbl_content` VALUES (110,1,'2179308','','مهمترین رسالت ما ...','<h4>مهمترین رسالت ما ...</h4>\r\n<h4><span style=\"color: #ff6600;\">نظام اســــتاد- شــــاگردی </span></h4>\r\n<p>توسعه توانمندی نیروی انسانی سازمان توسط پتانسیل درون سازمان</p>\r\n<p><a href=\"https://igx.ir/edx/fa/section-one/\">ادامه مطلب</a></p>','img_1737301370_1.jpg,','file_1737300820_fa.jpg','1403/11/4','fa','',NULL,'1737643980','0','','','',0,0,'مهمترین-رسالت-ما----','','','https://igx.ir/edx/fa/section-two/',0,NULL,NULL,'',''),(111,1,'2179308','','','','img_1737301370_1.jpg,','','1403/11/4','en','',NULL,'1737643980','0','','','',0,0,'','','','https://igx.ir/edx/fa/section-two/',0,NULL,NULL,'',''),(112,1,'22FCE21','','نظام استاد - شاگردی','<h4><span style=\"color: #ff6600;\">نظام استاد - شاگردی</span></h4>\r\n<p>توسعه توانمندی سرمایه انسانی سازمان توسط پتانسیل درون سازمان</p>\r\n<p><a href=\"yahoo.com\">ادامه مطلب</a></p>',',,,,,','','1403/10/13','fa','',NULL,'1735812032','0','','','',0,0,'نظام-استاد---شاگردی','','','',0,NULL,NULL,'',''),(126,3,'C0B0877','','تکیه بر راهنمایی و مربی‌گری تحولی اساسی در مدیریت منابع انسانی','<p>آیا تا به حال ارزش راهنمایی و مربی&zwnj;گری را در فرآیند مداوم مهارت&zwnj;آموزی در سازمان سنجیده&zwnj;اید؟</p>\r\n<p>به نظر شما چرا راهنمایی و مربی&zwnj;گری تا این حد در مدیریت منابع انسانی در جهان محوریت پیدا کرده؟</p>\r\n<p>آیا تا به حال برای نیروهای انسانی خود فرصت یادگیری مهارت&zwnj;های نرم را فراهم کرده&zwnj;اید؟</p>','','file_1737363698_fa.','1403/11/1','fa','',NULL,'1737363672','0','','','',0,0,'تکیه-بر-راهنمایی-و-مربی‌گری-تحولی-اساسی-در-مدیریت-منابع-انسانی','','','',NULL,NULL,NULL,'',''),(127,3,'C0B0877','','','','','file_1737363698_en.','1403/11/1','en','',NULL,'1737363672','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(128,3,'C3ED530','','شناسایی نیاز کارکنان با کمترین هزینه','<p style=\"text-align: right;\">چگونه می&zwnj;توانید از طریق فرآیند دقیق نیازسنجی به طور هدفمند نیازهای&nbsp; نیروی انسانی خود را به طور دقیق و مستمر شناسایی کنید؟</p>\r\n<p style=\"text-align: right;\">چطور می&zwnj;توانید با کمترین هزینه به توسعه مهارت و دانش کارکنان بپردازید؟</p>','','file_1737360787_fa.','1403/11/1','fa','',NULL,'1737360775','0','','','',0,0,'شناسایی-نیاز-کارکنان-با-کمترین-هزینه','','','',NULL,NULL,NULL,'',''),(129,3,'C3ED530','','','','','file_1737360787_en.','1403/11/1','en','',NULL,'1737360775','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(130,3,'5395542','','تحول در روش‌های آموزشی در عصر انقلاب تکنولوژی','<p>چه انتظاراتی از روش&zwnj;های نوین آموزش برای سازمان&zwnj;تان در سومین دهه&zwnj;ی قرن 21 دارید؟</p>\r\n<p>فن&zwnj;آوری نوین چه امکاناتی به شما می&zwnj;دهد؟ دانش و تجربه&zwnj;ی انباشته شده در طی زمان چه امکاناتی؟</p>\r\n<p>چگونه می&zwnj;توان از هر دو بیشترین بهره را برد؟</p>','','file_1737363597_fa.','1403/11/1','fa','',NULL,'1737363572','0','','','',0,0,'تحول-در-روش‌های-آموزشی-در-عصر-انقلاب-تکنولوژی','','','',NULL,NULL,NULL,'',''),(131,3,'5395542','','','','','file_1737363597_en.','1403/11/1','en','',NULL,'1737363572','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(132,4,'4D846F0','','ایجاد جریان پیوسته دانش و مهارت','','','','1403/10/16','fa','',NULL,'1736080903','0','','','',0,0,'ایجاد-جریان-پیوسته-دانش-و-مهارت','','','',NULL,NULL,NULL,'',''),(133,4,'4D846F0','','','','','','1403/10/16','en','',NULL,'1736080903','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(134,4,'643E859','','سنجش و ارزیابی اختصاصی مهارت‌ها','','','file_1736160474_fa.','1403/10/17','fa','',NULL,'1736160457','0','','','',0,0,'سنجش-و-ارزیابی-اختصاصی-مهارت‌ها','','','',NULL,NULL,NULL,'',''),(135,4,'643E859','','','','','file_1736160474_en.','1403/10/17','en','',NULL,'1736160457','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(136,4,'E65B902','','تهیه نقشه راه منحصر به فرد برای هر فراگیر','','','','1403/10/16','fa','',NULL,'1736080962','0','','','',0,0,'تهیه-نقشه-راه-منحصر-به-فرد-برای-هر-فراگیر','','','',NULL,NULL,NULL,'',''),(137,4,'E65B902','','','','','','1403/10/16','en','',NULL,'1736080962','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(138,4,'FD3E1FB','','پایش و ارزیابی پیشرفت مهارت آموزی','','','','1403/10/16','fa','',NULL,'1736080990','0','','','',0,0,'پایش-و-ارزیابی-پیشرفت-مهارت-آموزی','','','',NULL,NULL,NULL,'',''),(139,4,'FD3E1FB','','','','','','1403/10/16','en','',NULL,'1736080990','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(140,4,'806F1E9','','هویت بخشی نظام استاد-شاگردی با استقرار سامانه ExAcd','','','file_1736160342_fa.','1403/10/17','fa','',NULL,'1736160293','0','','','',0,0,'هویت-بخشی-نظام-استاد-شاگردی-با-استقرار-سامانه-exacd','','','',NULL,NULL,NULL,'',''),(141,4,'806F1E9','','','','','file_1736160342_en.','1403/10/17','en','',NULL,'1736160293','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(182,2,'890E4B6','','سامانه ExAcd','<h1 style=\"text-align: center;\"><strong><span style=\"color: #ff6600;\">سامانه ExAcd</span></strong></h1>\r\n<p>&nbsp;</p>\r\n<h1 style=\"text-align: center;\"><strong>رویکردی برای تعیین هدف و راهبری</strong><br /><strong>&nbsp;فرآیند یادگیری مهارت</strong></h1>\r\n<p style=\"text-align: center;\"><a href=\"https://igx.ir/edx/fa/section-one/\">ادامه مطلب</a></p>','img_1737301669_1.jpg,','','1403/11/17','fa','',NULL,'1738750718','0','','','',0,0,'سامانه-exacd','','','',NULL,'','','',''),(183,2,'890E4B6','','','','img_1737301669_1.jpg,','','1403/11/17','en','',NULL,'1738750718','0','','','',0,0,'','','','',NULL,'','','',''),(184,2,'CDF51C5','','حوزه‌های مهارت‌ آموزی','<h1 style=\"text-align: center;\"><strong><span style=\"color: #ff6600;\">حوزه&zwnj;های مهارت آموزی</span></strong></h1>\r\n<h1><strong>&nbsp;</strong></h1>\r\n<h1 style=\"text-align: center;\"><strong>کسب مهارت&zwnj;های مورد نیاز سازمان </strong><br /><strong>با بهره&zwnj;گیری از اساتید حرفه&zwnj;ای</strong><br /><strong>و با تجربه در منابع مختلف</strong></h1>\r\n<p style=\"text-align: center;\"><a href=\"https://igx.ir/edx/fa/course/\">ادامه مطلب</a></p>','img_1737301604_1.jpg,','','1403/11/17','fa','',NULL,'1738750642','0','','','',0,0,'حوزه‌های-مهارت‌-آموزی','','','',NULL,'','','',''),(185,2,'CDF51C5','','','','img_1737301604_1.jpg,','','1403/11/17','en','',NULL,'1738750642','0','','','',0,0,'','','','',NULL,'','','',''),(186,2,'1835346','','نظام استاد-شاگردی','<h2 style=\"text-align: center;\"><strong><span style=\"color: #ff6600;\">نظام استاد-شاگردی</span></strong></h2>\r\n<p>&nbsp;</p>\r\n<h2 style=\"text-align: center;\"><strong>مکانیزمی نوین به منظور </strong></h2>\r\n<h2 style=\"text-align: center;\"><strong>ارتقاء مهارت و توانمندسازی منابع انسانی</strong><br /><strong>در راستای حل مسائل سازمان</strong></h2>\r\n<p style=\"text-align: center;\"><a href=\"https://igx.ir/edx/fa/section-two/\">ادامه مطلب</a></p>','img_1737301202_1.jpg,','file_1737301230_fa.jpg','1403/11/17','fa','',NULL,'1738750674','0','','','',0,0,'نظام-استاد-شاگردی','','','',NULL,'','','',''),(187,2,'1835346','','','','img_1737301202_1.jpg,','','1403/11/17','en','',NULL,'1738750674','0','','','',0,0,'','','','',NULL,'','','',''),(190,3,'4A369D2','','فواید مشارکت در نظام استاد شاگردی برای کارکنان سازمان‌ها','<p style=\"text-align: right;\">شخص شما چه به عنوان مدیر و چه در هر رده سازمانی دیگری که هستید ، چه بهره&zwnj;هایی را می&zwnj;توانید از نظام استاد-شاگردی ببرید؟</p>\r\n<p style=\"text-align: right;\">آیا تا به حال بهره&zwnj;بردن از یک استاد راهنما را تجربه کرده&zwnj;اید؟</p>\r\n<p style=\"text-align: right;\">آیا تجربیات عملی شما می&zwnj;توانند برای افراد دیگری نیز راهگشا باشند؟</p>','','file_1737363541_fa.','1403/11/1','fa','',NULL,'1737363529','0','','','',0,0,'فواید-مشارکت-در-نظام-استاد-شاگردی-برای-کارکنان-سازمان‌ها','','','',NULL,NULL,NULL,'',''),(191,3,'4A369D2','','','','','file_1737363541_en.','1403/11/1','en','',NULL,'1737363529','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(192,3,'2B9BA21','','نظام استاد شاگردی، مسیر «یادگیری ناب»','<p style=\"text-align: right;\">آیا تا به حال به این اندیشیده&zwnj;اید که چطور می&zwnj;توانید اصول تولید ناب را در مهارت آموزی کارکنان پیاده سازید؟</p>\r\n<p style=\"text-align: right;\">چگونه می&zwnj;توانید در مدیریت منابع انسانی با کمینه&zwnj;سازی اتلاف منابع و زمان به بهره&zwnj;وری و بهبود مستمر و بیشینه دست یابید؟</p>','','file_1737363440_fa.','1403/11/1','fa','',NULL,'1737363414','0','','','',0,0,'نظام-استاد-شاگردی،-مسیر-«یادگیری-ناب»','','','',NULL,NULL,NULL,'',''),(193,3,'2B9BA21','','','','','file_1737363440_en.','1403/11/1','en','',NULL,'1737363414','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(194,3,'CE36914','','چرا نظام استاد شاگردی ؟','<p style=\"text-align: right;\">تا چه حد به فواید یک نظام مستدام مهارت آموزی برای سازمان&zwnj;تان اندیشیده&zwnj;اید؟</p>\r\n<p style=\"text-align: right;\">آیا کارمندانی دارید که اگر از فردا بر سرکار حاضر نباشند جایگزینی آن&zwnj;ها چالشی برای شما باشد؟</p>\r\n<p style=\"text-align: right;\">چرا مهارت آموزی را می&zwnj;توان و باید به عنوان یک فرآیند پیوسته در سازمان دید؟</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>','','file_1737360315_fa.','1403/11/1','fa','',NULL,'1737360292','0','','','',0,0,'چرا-نظام-استاد-شاگردی-؟','','','',NULL,NULL,NULL,'',''),(195,3,'CE36914','','','','','file_1737360315_en.','1403/11/1','en','',NULL,'1737360292','0','','','',0,0,'','','','',NULL,NULL,NULL,'',''),(198,1,'17C9443','','رسالت ما','','','file_1736671529_fa.mp4','1403/10/23','fa','',NULL,'1736671451','0','','','',0,0,'رسالت-ما','','','',0,NULL,NULL,'',''),(199,1,'17C9443','','','','','','1403/10/23','en','',NULL,'1736671451','0','','','',0,0,'','','','',0,NULL,NULL,'',''),(200,1,'15C6D62','','نظام','<p>بیبیسبیسبیسب</p>','','file_1736671585_fa.mp4','1403/10/23','fa','',NULL,'1736671558','0','','','',0,0,'نظام','','','',0,NULL,NULL,'',''),(201,1,'15C6D62','','','','','','1403/10/23','en','',NULL,'1736671558','0','','','',0,0,'','','','',0,NULL,NULL,'',''),(202,15,'C1878EC','','پلیمر آریا ساسول','<p>پروژه&zwnj;های انجام شده:</p>\r\n<p>OHSAS18001.ISO9001,ISO14001-جایزه ملی کیفیت ایران EFQM&amp;INQA</p>','img_1737300912_1.png,','file_1738396237_fa.','1403/11/13','fa','',NULL,'1738396233','0','','','',0,0,'پلیمر-آریا-ساسول','','','',NULL,'','','',''),(203,15,'C1878EC','','','','img_1737300912_1.png,','file_1738396237_en.','1403/11/13','en','',NULL,'1738396233','0','','','',0,0,'','','','',NULL,'','','',''),(204,15,'42F421F','','شهرداری قم','<p>پروژه&zwnj;های انجام شده:</p>\r\n<p>استقرار&nbsp;چرخه مدیریت بهره&zwnj;وری در شهرداری قم-مطالعه، طراحی و استقرار چرخه بهره&zwnj;وری و ارزیابی اثربخشی عملکرد</p>','img_1737300939_1.png,','file_1738396244_fa.','1403/11/13','fa','',NULL,'1738396240','0','','','',0,0,'شهرداری-قم','','','',NULL,'','','',''),(205,15,'42F421F','','','','img_1737300939_1.png,','file_1738396244_en.','1403/11/13','en','',NULL,'1738396240','0','','','',0,0,'','','','',NULL,'','','',''),(206,15,'2EF1985','','شهرداری تهران','<p>پروزه&zwnj;های انجام شده:</p>\r\n<p>مشاوره، نگهداری و توسعه سامانه HSE-نگهداشت سیستم مدیریت یکپارچه IMS- خدمات مشاوره در زمینه ارتقاء سیستم مدیریت کیفیت</p>','img_1737300965_1.png,','file_1738396252_fa.','1403/11/13','fa','',NULL,'1738396248','0','','','',0,0,'شهرداری-تهران','','','',NULL,'','','',''),(207,15,'2EF1985','','','','img_1737300965_1.png,','file_1738396252_en.','1403/11/13','en','',NULL,'1738396248','0','','','',0,0,'','','','',NULL,'','','',''),(208,15,'6917676','','توانیر و شرکت‌های تابعه','<p>پروژه&zwnj;های انجام شده :</p>\r\n<p>مطالعه، بررسی، آموزش، ارزیابی و تحلیل شکاف جهت استقرار مدیریت دارایی&zwnj;های فیزیکی- مشاوره مدیریت جهت پیاده&zwnj;سازی سیستم مدیریت دارایی&zwnj;های فیزیکی-مشاوره مدیریت جهت ارائه خدمات مدیریت دارایی&zwnj;های فیزیکی</p>','img_1737300987_1.png,','file_1738396261_fa.','1403/11/13','fa','',NULL,'1738396256','0','','','',0,0,'توانیر-و-شرکت‌های-تابعه','','','',NULL,'','','',''),(209,15,'6917676','','','','img_1737300987_1.png,','file_1738396261_en.','1403/11/13','en','',NULL,'1738396256','0','','','',0,0,'','','','',NULL,'','','',''),(210,15,'6CA3868','','خصوصی‌سازی ','<p style=\"text-align: right;\">پروژه&zwnj;های انجام شده:</p>\r\n<p style=\"text-align: right;\">ارزیابی&nbsp;عملکرد واحدهای دولتی واگذار شده به بخش خصوصی-ارزیابی عملکرد قبل و پس از واگذاری 63 شرکت واگذار شده به بخش غیردولتی توسط سازمان خصوصی&zwnj;سازی-ارزیابی عملکرد قبل و پس از واگذاری 18 شرکت واگذار شده به بخش غیردولتی توسط سازمان خصوصی&zwnj;سازی</p>','img_1737301014_1.png,','file_1738396266_fa.','1403/11/13','fa','',NULL,'1738396263','0','','','',0,0,'خصوصی‌سازی-','','','',NULL,'','','',''),(211,15,'6CA3868','','','','img_1737301014_1.png,','file_1738396266_en.','1403/11/13','en','',NULL,'1738396263','0','','','',0,0,'','','','',NULL,'','','',''),(212,15,'B02BDF6','','سازمان بنادر و دریانوردی','<p style=\"text-align: justify;\">پروژه&zwnj;های انجام شده:</p>\r\n<p style=\"text-align: justify;\">&nbsp;تهیه RFP جهت تدوین منابع آموزشی دریانوردان -&nbsp; مشاوره مدیریت در زمینه امور ممیزی وبررسی سوانح دریایی- مشاوره در امور آموزش، آزمون و صدور اسناد دریانوردی- مشاوره مدیریت در اجراء&zwnj;، ارزیابی و کنترل&nbsp; راهبردهای دریایی- بازنگری سند چشم انداز سازمان بنادر و دریانوردی- تدوین RFP جهت استخراج، پالایش و ترجمه اصلاحات به مقاوله نامه&zwnj;ها و پروتکل&zwnj;ها به روش پذیرش ضمنی-ارزیابی عملکرد و کنترل مانیتورینگ شاخص&zwnj;های عملکرد امور بندری&zwnj;، تدوین اهداف راهبردی مدیریت دریایی کشور در راستای ارتقای ایمنی، امنیت دریانوردی و حفظ محیط زیست</p>','img_1737301037_1.png,','file_1738396272_fa.','1403/11/13','fa','',NULL,'1738396268','0','','','',0,0,'سازمان-بنادر-و-دریانوردی','','','',NULL,'','','',''),(213,15,'B02BDF6','','','','img_1737301037_1.png,','file_1738396272_en.','1403/11/13','en','',NULL,'1738396268','0','','','',0,0,'','','','',NULL,'','','',''),(214,1,'7DA09B5','','قسمت دوم','','img_1737638059_1.jpg,','','1403/11/9','fa','',NULL,'1738053415','0','','','',0,0,'قسمت-دوم','','','قسمت دوم',0,'','ExAcd','',''),(215,1,'7DA09B5','','','','img_1737638059_1.jpg,','','1403/11/9','en','',NULL,'1738053415','0','','','',0,0,'','','','قسمت دوم',0,'','ExAcd','',''),(216,16,'12A475E','','2','','img_1737638085_1.jpg,','','1403/11/4','fa','',NULL,'1737638076','0','','','',0,0,'2','','','2',NULL,NULL,NULL,'