INSERT INTO `tbl_teacher` VALUES (1,'امینی','سیده محبوبه','','','','',0,'//','','۰۹۱۲۱۲۵۰۴۸۸','','۱۴۳۵۷۶۳۴۳۸','','','تهران، میدان ونک، خیابان برزیل شرقی، نبش بن بست نارنج، پلاک ۴.۲، طبقه دوم','sm.aminieng@gmail.com','202cb962ac59075b964b07152d234b70',0,'۰۲۱-۸۸۷۹۷۵۴۴',0,'profile_1624689892.jpg','','',0,'fa','','','','دکترای مدیریت بازرگانی','<p>مدیر عامل گروه کارشناسان ایران</p>\r\n<p>[short]</p>\r\n<p>لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ و با استفاده از طراحان گرافیک است.</p>','http://www.igx.ir/','http://www.igx.ir/','http://www.igx.ir/'),(2,'انتصاریان',' فرزین','','','','',0,'//','','۰۹۱۲۱۲۵۰۴۸۸','','۱۴۳۵۷۶۳۴۳۸','','','تهران، میدان ونک، خیابان برزیل شرقی، نبش بن بست نارنج، پلاک ۴.۲، طبقه دوم','mail@igx.ir','$2y$12$7AI2zU8fDFf148g2V0ENjOLeEB41NFStMIYHlWVen8yY3BIsP0EL.',0,'۰۲۱-۸۸۷۹۷۵۴۴',0,'profile_1669180714.jpg','','',0,'fa','','','','فوق ليسانس مكانيك','<p>موسس گروه کارشناسان ایران</p>\r\n<p>[short]</p>\r\n<p style=\"text-align: justify;\">مهندس فرزین انتصاریان فوق لیسانس مهندسی مکانیک در سال ۱۳۴۷ - موسس گروه کارشناسان ایران (اولین موسسه بازرسی ایرانی)</p>\r\n<p style=\"text-align: justify;\">اولین کارشناس موسسات رده بندی و بازرسی بین المللی در امور صنایع و کشتی و کالا</p>\r\n<p style=\"text-align: justify;\">عضویت در مجامع و انجمن های ملی و بین اللملی</p>\r\n<p style=\"text-align: justify;\">صاحب امتیاز فصلنامه کیفیت و مدیریت و انتشارات کیفیت و مدیریت</p>\r\n<p style=\"text-align: justify;\">انجام ده ها مورد پژوهش های راهبردی در کشور&nbsp;</p>\r\n<p style=\"text-align: justify;\">دبیر پنج دوره کنفرانس بین المللی مدیریت کیفیت ایران</p>','http://www.igx.ir/','http://www.igx.ir/','http://www.igx.ir/'),(3,'امینیان','پیمان','','','','',0,'//','','۰۹۱۳۳۰۸۵۱۱۷','','۱۴۳۵۷۶۳۴۳۸','','','تهران، میدان ونک، خیابان برزیل شرقی، نبش بن بست نارنج، پلاک ۴.۲، طبقه دوم','peiman.aminian@experts-group.com','$2y$12$v08TjS5.LH8ddKOZKeyiS.5FZ5QFvOz2vEeYrFR17qmuEqeY4pTv6',0,'۰۲۱-۸۸۷۹۷۵۴۴',0,'profile_1624691071.jpg','','',0,'fa','','','','مدیریت مالی','<p>مدیر عامل&nbsp;شرکت اکسپرتز گروپ</p>\r\n<p>[short]</p>\r\n<p>لورم ایپسوم متن ساختگی با تولید سادگی نامفهوم از صنعت چاپ و با استفاده از طراحان گرافیک است.</p>\r\n<p>&nbsp;</p>','http://www.igx.ir/','http://www.igx.ir/','http://www.igx.ir/'),(4,'شهرخی','محمود','','','','',0,'//','','','','','','','','09163656344','b7f1fc98a0e30feb5eb91074526c8069',0,'09163656344',0,'profile_1666093482.png','','',0,'fa','','','','دکترای صنایع','','','',''),(5,'شفیعی','رضا','','','','',0,'//','','','','','','','','shafiei@gmail.com','e10adc3949ba59abbe56e057f20f883e',0,'',0,'profile_1629194413.jpg','','',0,'fa','','','','دکترای صنایع','','','',''),(6,'طاهری‌نیک','فرستی','','','','',0,'//','','','','','','','','','$2y$12$3S7IJ.DFtM1YU6hsnehu9O0.Dnii/8QKA4EU1B4A.jkbVckZ1j8qq',0,'',0,'profile_1629190353.jpg','','',0,'fa','','','','مهندسی صنایع','<p>&nbsp;</p>\r\n<p>[short]</p>\r\n<p style=\"text-align: justify;\">مسئوا اجرا و راهبری سیستم های مدیریت کیفیت و HSE در حوزه نفت و گاز و پتروشیمی<br />طراح و مدرس دوره های آموزشی کیفیت و HSE<br />کارشناس اجرایی سیستم های مدیریت کیفیت و HSE در پروژه های نفت و گاز<br />مشاور و استقرار سیستم های مدیریت کیفیت HSE-MS در سازمان ها</p>','','',''),(8,'باورصاد صالح‌پور','ایمان','','','','',0,'//','','','','','','','','09163815168','82984a76dbd3073ef5ffb9176dc25f55',0,'09163815168',0,'profile_1629194771.jpg','','',0,'fa','','','','دکترای صنایع','','','',''),(9,'جوکار','مهدی','','','','',0,'//','','','','','','','','','$2y$12$jq6ug0mLYXs///A81EiT3OgbZgqIBZadMcWQgXkQSNWGGyrvMXEQS',0,'',0,'','','',0,'fa','','','','کارشناسی ارشد مدیریت صنعتی','','','',''),(10,'عالی‌پور','مژگان','','','','',0,'//','','','','','','','','','$2y$12$Q6iSM0NHGI5ydimoNz3xne5XHfwV3JDMNpy/YhT4nYwyC7PxZ8GNe',0,'',0,'','','',0,'fa','','','','کارشناس ارشد مدیریت بازرگانی','','','',''),(11,'لوایی','محمد','','','','',0,'//','','','','','','','','','$2y$12$3JU3nH8NW7K8eeCdxG6kV.a6v/8EDvmBM1NQdTXbMaFjxasa0YbEy',0,'',0,'','','',0,'fa','','','','دکترای آمار و احتمال','','','',''),(13,'کارشناسان ایران','گروه'