INSERT INTO `tbl_workshop` VALUES (1,'18','مدیریت کیفیت فراگیر ','123','30D305D','',100000,'{\"1\":\"2\",\"2\":\"1\"}','img_1653281806_1.jpg,',1,'1400/03/17 : قبل از ظهر:09:38',0,'trpm','<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><strong>هدف از این دوره</strong>&nbsp;</span>ایجاد توانایی و مهارت در کارشناسان به عنوان عوامل اجرا و برقراری صحیح سیستم مدیریت کیفیت بر مبنای ISO 9001 2015 می باشد .</p>\r\n<p style=\"text-align: justify;\">[short]</p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><strong>هدف از این دوره</strong>&nbsp;</span>ایجاد توانایی و مهارت در کارشناسان به عنوان عوامل اجرا و برقراری صحیح سیستم مدیریت کیفیت بر مبنای iso9001 2015 می باشد .</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">&nbsp;<strong>محتوی معرفی دوره :</strong></p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">هر چند که مفهوم کیفیت همیشه در زندگی بشر&nbsp;مطرح بوده است ولی دانش کیفیت و&nbsp;<strong>مدیریت کیفیت</strong>&nbsp;علمی برمی&zwnj;گردد&nbsp;به اولیل قرن گذشته که در ادامه شرح مختصری از آن ارائه می&zwnj;شود:</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">سال&nbsp;۱۹۲۴ :&nbsp;پدر علم کیفیت را&nbsp;دکتر والتر شوهارت آمریکایی می&zwnj;دانند که در آن&nbsp;سال در آزمایشگاه های شرکت&nbsp;<span dir=\"LTR\">Bell</span>&nbsp;سیستمی را به وجود آورد که می<span dir=\"LTR\">&lrm;</span>توانست واریانس سیستم های تولید را&nbsp;اندازه<span dir=\"LTR\">&lrm;</span>گیری کند. این سیستم به نام (کنترل آماری فرایند) یا&nbsp;<span dir=\"LTR\">SPC</span>&nbsp;مشهور شد. دکتر شوهارت در سال&nbsp;۱۹۳۱ کتابی با عنوان &laquo;کنترل اقتصادی کیفیت محصولات صنعتی&raquo; منتشر کرد. در این کتاب او به موضوع &laquo;کنترل کیفیت آماری&raquo; پرداخت.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">سال&nbsp;۱۹۴۶ :&nbsp;در این سایت بارها اشاره شد که جنگ جهانی دوم یکی از مهمترین خاستگاه&zwnj;های علوم مدیریت بود به طوری که بعضی از علوم مدیریت در جنگ متولد شدند و بعضی هم در جنگ رشد پیدا کردند چون پیدا کردن راهکار در جنگ جزو بالاترین &nbsp;نیازها بود&nbsp;و این نیازها محرک تحقیق و بعد هم تولید علم بودند. پس از جنگ جهانی دوم نیروهای حرفه<span dir=\"LTR\">&lrm;</span>ای تولید در ژاپن &laquo;سازمان غیرانتفاعی اتحادیه مهندسان و دانشمندان ژاپن&raquo; را&nbsp;تأسیس کردند. در همین سال، جامعه کنترل کیفیت آمریکا&raquo; نیز تشکیل شد.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">شاگرد شوهارت ادوارد دمینگ که یک فیزیکدان با گرایش ریاضی بود و در بخش کشاورزی و دفتر تحقیقات آمریکا کار می<span dir=\"LTR\">&lrm;</span>کرد، موظف شد تا سیستم کنترل آماری فرایند را به کارکنان صنایع دفاعی آمریکا آموزش دهد.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">سال ۱۹۵۰:&nbsp;اتحادیه متخصصان علوم و مهندسین ژاپن (<span dir=\"LTR\">JUSE</span>) از دمینگ دعوت کردند تا&nbsp;<span dir=\"LTR\">SPC</span>&nbsp;و روش های کنترل کیفیت را در کشور ژاپن آموزش دهد. ژاپنی<span dir=\"LTR\">&lrm;</span>ها به سرعت خود را با آموزش های دمینگ هماهنگ ساخته و در این روش ها تغییراتی به وجود آوردند. خیلی جاها از دمینگ به عنوان پدر کیفیت یاد می&zwnj;شود. بهرحال شروع این حرکت با شوهارت بوده ولی به اوج رساندن آن&nbsp;با دمینگ بوده است.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">قسمت جالب مساله هم در این است&nbsp;که دمینگ یک آمریکایی بود ولی اصولش و تفکرات کیفیتی او&nbsp;در ژاپن مورد پذیرش بالایی قرار گرفت و این کشور تبدیل به راهبر علم مدیریت کیفیت شد. شاید چون فرهنگ ژاپنی بیشتر از هر فرهنگ دیگری با مفاهیم مد نظر دمینگ همخوانی داشت.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">&nbsp;سال ۱۹۵۱:&nbsp;اتحادیه دانشمندان و مهندسین ژاپنی (<span dir=\"LTR\">JUSE</span>) جایزه دمینگ که عالیترین جایزه کیفیت در ژاپن به حساب می<span dir=\"LTR\">&lrm;</span>آید را&nbsp;با هدف افزایش سطح کیفیت صنعت در ژاپن ایجاد کردند. دمینگ به پاس خدماتی که به توسعه کیفیت در ژاپن انجام داد، بزرگترین جایزه ژاپن به نام &laquo;مدال افتخار امپراطور برای سازندگان اقتصاد ژاپنی&raquo; را&nbsp;دریافت کرد.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">سال ۱۹۵۱:&nbsp;دکتر فینگبام کتابی تحت عنوان &laquo;کنترل کیفیت فراگیر&raquo; منتشر کرد. در این کتاب او به جای &laquo;کنترل کیفیت آماری&raquo; از &laquo;کنترل کیفیت فراگیر&raquo; سخن به میان آورد.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">سال ۱۹۵۴: جوزف جوران اهمیت درگیر نمودن تمام بخش ها در پیگیری امر کیفیت و اهمیت رضایت مشتری را&nbsp;به جای امر ساده تبعیت از مشخصات محصول ژاپنی<span dir=\"LTR\">&lrm;</span>ها تاکید کرد.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">سال ۱۹۶۲:&nbsp;کاآرو ایشیکاوا ایده و تفکرات جوران و فینگبام را&nbsp;بسط داده و موضوع مشتریان داخلی را&nbsp;که دریافت<span dir=\"LTR\">&lrm;</span>کنندگان بروندادهای داخل سازمان هستند علاوه بر مشتریان خارجی سازمان مطرح کرد. ایشیکاوا بر مبنای کار متخصصین علوم رفتاری و نظریه سلسله مراتب نیازهای مازلو و تئوری&nbsp;<span dir=\"LTR\">X</span>&nbsp;و&nbsp;<span dir=\"LTR\">Y</span>&nbsp;مک<span dir=\"LTR\">&lrm;</span>گریگور ، &nbsp;واژه &laquo;کانون<span dir=\"LTR\">&lrm;</span>های کیفیت&raquo; را&nbsp;مطرح کرد.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">اواخر دهه ۱۹۷۰:&nbsp;آمریکایی<span dir=\"LTR\">&lrm;</span>ها و اروپایی<span dir=\"LTR\">&lrm;</span>ها که متوجه پیشی گرفتن ژاپنی<span dir=\"LTR\">&lrm;</span>ها در تسخیر بازارهای جهانی شدند، به فکر استفاده از نگرش&nbsp;<span dir=\"LTR\">TQM</span>&nbsp;در مدیریت های خود افتادند.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">سال&nbsp;۱۹۸۷ :&nbsp;آمریکا در مقابل جایزه دمینگ، جایزه<span dir=\"LTR\">&lrm;</span>ای را به نام &laquo;مالکوم بالدریج&raquo; ابداع کرد. این جایزه برای معرفی سازمان هایی که به بالا بردن سطح کیفیت خود و اجرای&nbsp;<span dir=\"LTR\">TQM</span>&nbsp;دست یافته<span dir=\"LTR\">&lrm;</span>اند، طراحی شد.</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">&nbsp;</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\"><strong>اهداف رفتاری دوره ( نوع رفتار و قابلیت هایی که انتظار داریم فراگیر، پس از یادگیری دوره فعلی به آن برسد)</strong>&nbsp;:</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">---------------------------</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">-------------------------</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\"><strong>روش آموزش :</strong>&nbsp;ویدئو&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;متن&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;کارگاه&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; پادکست&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; سایر&nbsp;</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">&nbsp;</p>\r\n<p dir=\"RTL\" style=\"text-align: justify;\"><strong>مشخصات سر فصل های دوره :&nbsp;</strong></p>\r\n<table style=\"height: 137px;\" width=\"458\">\r\n<tbody>\r\n<tr>\r\n<td style=\"text-align: center;\">ردیف</td>\r\n<td style=\"text-align: center;\">سر فصل&nbsp;</td>\r\n<td style=\"text-align: center;\">نظری</td>\r\n<td style=\"text-align: center;\">عملی</td>\r\n</tr>\r\n<tr>\r\n<td>۱</td>\r\n<td>----------</td>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>۲</td>\r\n<td>----------</td>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>۳</td>\r\n<td>-------------</td>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>۴</td>\r\n<td>--------</td>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>۵</td>\r\n<td>------</td>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>۶</td>\r\n<td>----------</td>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>۷</td>\r\n<td>------</td>\r\n<td>&nbsp;</td>\r\n<td>&nbsp;</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p dir=\"RTL\" style=\"text-align: justify;\">&nbsp;</p>\r\n<h1>دوره های پیشنهادی :</h1>\r\n<p>تشریح الزامات و مستند سازی استاندارد ISO 9001 2015&nbsp; - ممیزی داخلی ISO 9001 2015</p>',0,0,'1400/03/08','5,6,7,9,',0,18,0,1,'1400/05/28','1401/05/28','کتاب استاندارد ملی ایران ISO 9000 2015','کارگاه','مدیران - کارشناسان','استاندارد ۹۰۰۱۵','۱۰۰ ساعت');
